package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class UpperEnglishNumberWordsTest {
 @Test public void independentBoundarySpellingsAndVariantsKeepSpellingStrict(){Map<Integer,String> examples=Map.of(101,"one hundred and one",105,"one hundred and five",110,"one hundred and ten",200,"two hundred",909,"nine hundred and nine",999,"nine hundred and ninety-nine",1000,"one thousand");for(var e:examples.entrySet()){assertEquals(e.getValue(),EnglishNumberWords.words(e.getKey()));Question q=EnglishNumberWords.make("numberToEnglishWords",e.getKey());q.answers=new String[]{"wrong key"};assertTrue(new Checker().check(q,List.of(),List.of(e.getValue())).correct());assertTrue(new Checker().check(q,List.of(),List.of(e.getValue().replace(" and "," ").toUpperCase().replace('-',' '))).correct());assertFalse(new Checker().check(q,List.of(),List.of("and "+e.getValue())).correct());assertFalse(new Checker().check(q,List.of(),List.of(""+e.getKey())).correct());}assertFalse(EnglishNumberWords.matches("nine hundred and fourty-nine","nine hundred and forty-nine"));Question q=EnglishNumberWords.make("numberToEnglishWords",1000);assertEquals(4,HelpPlan.forQuestion(q).size());assertTrue(HelpPlan.forQuestion(q).step(1).accepts("0"));q.prompt=q.prompt.replace("1000","1001");assertNull(EnglishNumberWords.publicValue(q));}
 @Test public void bothYearThreeDomainsExhaust1001BeforeOldest(){for(String id:List.of("englishWordsToNumber","numberToEnglishWords")){Generator g=new Generator(new Random(126));var limits=GlobalCurriculum.limits("england-primary-2021-v1",id,3);List<String> recent=new ArrayList<>();Set<Integer> values=new HashSet<>();for(int i=0;i<=1000;i++){Question q=g.next(id,recent,true,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());int n=EnglishNumberWords.publicValue(q);assertTrue(values.add(n));q.answers=new String[]{"poison"};assertTrue(new Checker().check(q,List.of(),List.of(id.equals("numberToEnglishWords")?EnglishNumberWords.words(n):""+n)).correct());assertTrue(q.choices.isEmpty());HelpPlan p=HelpPlan.forQuestion(q);assertFalse(p.canTransfer());assertEquals(n==1000?4:n>=100?3:2,p.size());}assertEquals(1001,values.size());assertEquals(recent.get(0),g.next(id,recent,false,limits).signature());}Learning.Profile p=new Learning.Profile();GlobalCurriculum.chooseCountry(p,"GB");GlobalCurriculum.choosePack(p,"england-primary-2021-v1");assertTrue(GlobalCurriculum.pack(p).inGrade("englishWordsToNumber",3));}
}
